from netgraph.graph import Graph
g = Graph(3); g.add_edge(0, 0)
assert g.is_bipartite() is False          # self-loop is an odd cycle
assert Graph(0).is_bipartite() is True
g = Graph(3); g.add_edge(0, 1); g.add_edge(1, 1)
s = g.subgraph([1, 0])
assert s.edges() == [(0, 0), (0, 1)] and s.edge_count() == 2
try:
    g.subgraph([0, 0]); raise SystemExit("expected ValueError")
except ValueError:
    pass
print("edge cases ok")
